<!doctype html><html lang="pt-BR"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ConnectPlus — Gerador de Imagens V2</title>
<style>
:root{--bg:#07101e;--card:#0e192b;--text:#f1f5ff;--muted:#93a3bf;--p:#667eea;--p2:#764ba2;--b:#223653}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:linear-gradient(135deg,#050a12,#10203a);color:var(--text);font:15px Arial}.wrap{max-width:1050px;margin:auto;padding:22px 15px}.top{display:flex;gap:12px;align-items:center;margin-bottom:18px}.mark{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(135deg,var(--p),var(--p2));font-weight:bold;font-size:20px}.top h1{margin:0;font-size:23px}.top p{margin:4px 0;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#0d182aee;border:1px solid var(--b);border-radius:18px;padding:18px;box-shadow:0 15px 40px #0005}.drop{border:2px dashed #385078;border-radius:15px;background:#0a1424;padding:35px 16px;text-align:center;cursor:pointer}.drop b{display:block;font-size:17px;margin-bottom:7px}.drop span{color:var(--muted)}#file{display:none}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:13px}.field label{display:block;color:var(--muted);font-size:12px;margin-bottom:6px}.field input,.field select{width:100%;padding:11px;border-radius:10px;border:1px solid var(--b);background:#091322;color:var(--text)}.opts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px}.opt{background:#0a1424;border:1px solid var(--b);border-radius:10px;padding:10px}.wide{grid-column:1/-1}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}button{border:0;border-radius:10px;padding:11px 14px;background:linear-gradient(135deg,var(--p),var(--p2));color:white;font-weight:bold;cursor:pointer}.sec{background:#1a2a45}.ok{color:#70e0ae;font-size:13px;margin-top:12px}.hint{color:var(--muted);font-size:12px;line-height:1.5;margin-top:12px}.preview{height:330px;display:grid;place-items:center;overflow:hidden;border-radius:14px;background:#e8ecf4;background-image:linear-gradient(45deg,#d5dbe6 25%,transparent 25%),linear-gradient(-45deg,#d5dbe6 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#d5dbe6 75%),linear-gradient(-45deg,transparent 75%,#d5dbe6 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}.preview img{max-width:100%;max-height:100%;object-fit:contain}.empty{color:#64748b}.file{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:10px;margin-top:7px;border:1px solid var(--b);border-radius:10px;background:#091322}.file small{display:block;color:var(--muted);margin-top:3px}@media(max-width:760px){.grid{grid-template-columns:1fr}.row,.opts{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body><div class="wrap">
<header class="top"><div class="mark">CP</div><div><h1>Gerador de Imagens</h1><p>ConnectPlus • WebP • PNG • SVG • Android XML</p></div></header>
<div class="grid"><section class="card">
<div class="drop" id="drop"><b>Arraste sua imagem aqui</b><span>ou toque para selecionar PNG, JPG, JPEG, WebP ou SVG</span><input id="file" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></div>
<div class="row"><div class="field"><label>Nome</label><input id="name" value="logo"></div><div class="field"><label>Fundo</label><select id="bg"><option value="transparent">Transparente</option><option value="#fff">Branco</option><option value="#000">Preto</option></select></div></div>
<div class="row"><div class="field"><label>Largura</label><input id="w" type="number" value="512" min="1" max="4096"></div><div class="field"><label>Altura</label><input id="h" type="number" value="512" min="1" max="4096"></div></div>
<div class="opts"><label class="opt"><input id="webp" type="checkbox" checked> WebP</label><label class="opt"><input id="png" type="checkbox" checked> PNG</label><label class="opt"><input id="svg" type="checkbox" checked> SVG</label><label class="opt"><input id="xml" type="checkbox" checked> Android XML</label><label class="opt wide"><input id="vector" type="checkbox"> Vetorização aproximada (SVG/XML)</label></div>
<div class="row" id="vo" style="display:none"><div class="field"><label>Resolução do vetor</label><select id="vs"><option>48</option><option selected>64</option><option>96</option><option>128</option></select></div><div class="field"><label>Cores máximas</label><select id="cs"><option>4</option><option selected>8</option><option>12</option><option>16</option></select></div></div>
<div class="buttons"><button id="gen">GERAR ARQUIVOS</button><button id="clear" class="sec">Limpar</button><button id="all" class="sec" style="display:none">BAIXAR TUDO</button></div>
<div id="status" class="ok"></div><div class="hint">A vetorização aproximada cria SVG e Android XML com formas geométricas e cores reduzidas. Para fotos e banners, use WebP/PNG. Sem vetorização, o SVG preserva a imagem raster dentro do SVG.</div>
</section><section class="card"><div id="preview" class="preview"><div class="empty">A pré-visualização aparecerá aqui.</div></div><div id="results"></div></section></div></div>
<script>
let img=null,url=null,files=[];
const $=x=>document.getElementById(x),drop=$('drop'),input=$('file');
drop.onclick=()=>input.click();drop.ondragover=e=>{e.preventDefault();drop.style.borderColor='#667eea'};drop.ondragleave=()=>drop.style.borderColor='#385078';drop.ondrop=e=>{e.preventDefault();if(e.dataTransfer.files[0])load(e.dataTransfer.files[0])};input.onchange=()=>{if(input.files[0])load(input.files[0])};$('vector').onchange=()=>{$('vo').style.display=$('vector').checked?'grid':'none'};
function load(f){if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(f);const im=new Image();im.onload=()=>{img=im;$('w').value=im.naturalWidth;$('h').value=im.naturalHeight;$('name').value=f.name.replace(/\.[^.]+$/,'').replace(/[^a-zA-Z0-9_-]/g,'_');$('preview').innerHTML='';const p=new Image();p.src=url;$('preview').appendChild(p)};im.src=url}
function canvas(w=+$('w').value,h=+$('h').value){const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d'),bg=$('bg').value;if(bg!='transparent'){x.fillStyle=bg;x.fillRect(0,0,w,h)}if(img){const r=Math.min(w/img.naturalWidth,h/img.naturalHeight),nw=img.naturalWidth*r,nh=img.naturalHeight*r;x.drawImage(img,(w-nw)/2,(h-nh)/2,nw,nh)}return c}
function dl(b,n){const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)}
function B(s,t){return new Blob([s],{type:t})}
function rasterSVG(c){return `<svg xmlns="http://www.w3.org/2000/svg" width="${c.width}" height="${c.height}" viewBox="0 0 ${c.width} ${c.height}"><image href="${c.toDataURL('image/png')}" width="${c.width}" height="${c.height}"/></svg>`}
function vectorCells(){const n=+$('vs').value,c=canvas(n,n),d=c.getContext('2d').getImageData(0,0,n,n).data,counts=new Map(),a=[];for(let y=0;y<n;y++)for(let x=0;x<n;x++){let i=(y*n+x)*4;if(d[i+3]<20)continue;let r=Math.round(d[i]/64)*64,g=Math.round(d[i+1]/64)*64,b=Math.round(d[i+2]/64)*64,k=r+','+g+','+b;counts.set(k,(counts.get(k)||0)+1);a.push({x,y,r,g,b,k})}let keep=new Set([...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,+$('cs').value).map(x=>x[0]));return {n,cells:a.filter(q=>keep.has(q.k))}}
function vsvg(){let {n,cells}=vectorCells(),sx=+$('w').value/n,sy=+$('h').value/n,s=`<svg xmlns="http://www.w3.org/2000/svg" width="${$('w').value}" height="${$('h').value}" viewBox="0 0 ${$('w').value} ${$('h').value}">`;for(const q of cells)s+=`<rect x="${q.x*sx}" y="${q.y*sy}" width="${sx+.2}" height="${sy+.2}" fill="rgb(${q.r},${q.g},${q.b})"/>`;return s+'</svg>'}
function vxml(){let {n,cells}=vectorCells(),sx=120/n,sy=120/n,s='<?xml version="1.0" encoding="utf-8"?>\\n<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="120dp" android:height="120dp" android:viewportWidth="120" android:viewportHeight="120">\\n';for(const q of cells){let col='#'+[q.r,q.g,q.b].map(v=>Math.max(0,Math.min(255,v)).toString(16).padStart(2,'0')).join('');let x=q.x*sx,y=q.y*sy,w=sx+.2,h=sy+.2;s+=`<path android:fillColor="${col}" android:pathData="M${x.toFixed(2)},${y.toFixed(2)}h${w.toFixed(2)}v${h.toFixed(2)}h-${w.toFixed(2)}z"/>\\n`}return s+'</vector>'}
function render(){ $('results').innerHTML='<b>Arquivos gerados</b>'+files.map((f,i)=>`<div class="file"><div><b>${f.n}</b><small>${Math.max(1,Math.round(f.b.size/1024))} KB</small></div><button class="sec" onclick="dl(files[${i}].b,files[${i}].n)">Baixar</button></div>`).join('');$('all').style.display=files.length?'inline-block':'none'}
$('gen').onclick=()=>{if(!img){alert('Selecione uma imagem primeiro.');return}files=[];$('status').textContent='Gerando...';let base=($('name').value||'imagem').replace(/[^a-zA-Z0-9_-]/g,'_'),c=canvas(),jobs=[];if($('png').checked)jobs.push(new Promise(r=>c.toBlob(b=>{files.push({n:base+'.png',b});r()},'image/png')));if($('webp').checked)jobs.push(new Promise(r=>c.toBlob(b=>{files.push({n:base+'.webp',b});r()},'image/webp',.95)));if($('svg').checked)files.push({n:base+'.svg',b:B($('vector').checked?vsvg():rasterSVG(c),'image/svg+xml')});if($('xml').checked)files.push({n:base+'.xml',b:B($('vector').checked?vxml():'<?xml version="1.0" encoding="utf-8"?><vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="120dp" android:height="120dp" android:viewportWidth="120" android:viewportHeight="120"><path android:fillColor="#00000000" android:pathData="M0,0h120v120h-120z"/></vector>','application/xml')});Promise.all(jobs).then(()=>{$('status').textContent=files.length+' arquivo(s) gerado(s).';render();files.forEach(f=>dl(f.b,f.n))})}
$('all').onclick=()=>files.forEach(f=>dl(f.b,f.n));$('clear').onclick=()=>{img=null;files=[];input.value='';if(url)URL.revokeObjectURL(url);url=null;$('preview').innerHTML='<div class="empty">A pré-visualização aparecerá aqui.</div>';$('results').innerHTML='';$('status').textContent='';$('all').style.display='none'};
</script></body></html>